// Auto-generated by scripts/sync-views.mjs — order matches VIEW_META.
// Do not document.write every view. Hundreds of parser-blocking scripts
// kept the tab spinner going. ObservatoryEnsureView(id) loads one
// view's css+js the first time it is shown.
(function () {
  var VIEWS = ["route","live","delay","funnel","windows","usage","compose","rings","accounts","budget","burn","burnrate","candle","chord","forecast","latency","latrank","league","marimekko","network","sankey","stream","swarm","treemap","waterfall"];
  var BUILTIN = { route: 1, radar: 1, loom: 1, rhythm: 1, rings: 1, quota: 1 };
  window.ObservatoryManifest = VIEWS;
  var pending = {};
  window.ObservatoryEnsureView = function (id) {
    if (!id || BUILTIN[id]) return Promise.resolve(false);
    if (window.ObservatoryViews && window.ObservatoryViews[id]) return Promise.resolve(true);
    if (pending[id]) return pending[id];
    pending[id] = new Promise(function (resolve) {
      var css = document.createElement('link');
      css.rel = 'stylesheet';
      css.href = 'assets/views/' + id + '.css';
      document.head.appendChild(css);
      var s = document.createElement('script');
      s.src = 'assets/views/' + id + '.js';
      s.onload = function () { resolve(!!(window.ObservatoryViews && window.ObservatoryViews[id])); };
      s.onerror = function () { resolve(false); };
      document.head.appendChild(s);
    });
    return pending[id];
  };
})();

/* Stage hosts are created on demand. Seeding every view div at startup
   made the first paint heavier than the route view needs. Built-ins other
   than route still get a host immediately. */
(function () {
  var BUILTIN_HOSTS = ['radar', 'loom', 'rhythm', 'rings', 'quota'];
  window.ObservatoryEnsureHost = function (id) {
    if (!id || id === 'route') return null;
    var existing = document.getElementById('view-' + id);
    if (existing) return existing;
    var stage = document.querySelector('.route-stage');
    if (!stage) return null;
    var d = document.createElement('div');
    d.className = 'stage-view';
    d.id = 'view-' + id;
    d.hidden = true;
    stage.appendChild(d);
    return d;
  };
  function seedBuiltins() {
    BUILTIN_HOSTS.forEach(window.ObservatoryEnsureHost);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', seedBuiltins);
  else seedBuiltins();
})();
